    CREATE TABLE "Testimonials" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Url" character varying(1000) NOT NULL,
        "CloudinaryPublicId" character varying(300),
        "Source" integer NOT NULL,
        "Caption" character varying(140),
        "Width" integer NOT NULL,
        "Height" integer NOT NULL,
        "IsPublished" boolean NOT NULL,
        "SortOrder" integer NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_Testimonials" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_Testimonials_Size" CHECK ("Width" BETWEEN 1 AND 20000 AND "Height" BETWEEN 1 AND 20000),
        CONSTRAINT "CK_Testimonials_Source" CHECK ("Source" IN (0, 1, 2))
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261124172915_Testimonials') THEN
    CREATE INDEX "IX_Testimonials_IsPublished_SortOrder" ON "Testimonials" ("IsPublished", "SortOrder");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261124172915_Testimonials') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20261124172915_Testimonials', '8.0.11');
    END IF;
END $EF$;
COMMIT;

